-- Migración: agregar columnas de imagen/porción/unidades a alimentos
-- y fusionar los 97 alimentos hardcodeados de la app con los 141 ya sembrados.
ALTER TABLE alimentos
  ADD COLUMN IF NOT EXISTS imagen_url text,
  ADD COLUMN IF NOT EXISTS porcion_base_g numeric DEFAULT 100,
  ADD COLUMN IF NOT EXISTS unidades jsonb DEFAULT '[]'::jsonb;

